-- Run once in MySQL Workbench using the administrator connection.
-- Password hashes must be generated by the application password library.
-- This creates no accounts and does not change existing QA records.
USE doctrace;

CREATE TABLE app_users (
    user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    username VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    password_hash VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    PRIMARY KEY (user_id),
    UNIQUE INDEX uq_app_users_username (username),
    CONSTRAINT chk_app_users_active CHECK (is_active IN (0, 1))
) ENGINE=InnoDB
  DEFAULT CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

GRANT SELECT, INSERT, UPDATE ON doctrace.app_users
    TO 'doctrace_app'@'127.0.0.1';

DESCRIBE app_users;
SHOW INDEX FROM app_users WHERE Key_name = 'uq_app_users_username';
SELECT COUNT(*) AS user_count FROM app_users;
